    o += "<path " + cls("tooth", 1) + hot(opt.hot && opt.hot.teeth) + ' d="' + D.dnPath(D.dnCrown(s, true, form, D).map(Dn), v, true) + '"/>';
    var top = D.dnOff(D.MAND.slice(1, D.MAND_TOP - 2), D.MUC).filter(function (p) { return p[0] > D.LB_X; });
